inline std::vector<unsigned char> decodeRgba() {
    std::vector<unsigned char> out;
    out.resize(static_cast<std::size_t>(kWidth) * static_cast<std::size_t>(kHeight) * 4u);

    std::size_t outPos = 0;
    std::size_t pos = 0;
    while (pos + 3 <= kRle.size() && outPos < out.size()) {
        const std::uint16_t count =
            static_cast<std::uint16_t>(kRle[pos]) |
            (static_cast<std::uint16_t>(kRle[pos + 1]) << 8);
        const std::uint8_t index = kRle[pos + 2];
        pos += 3;

        const std::size_t runBytes = static_cast<std::size_t>(count) * 4u;
        const std::size_t palettePos = static_cast<std::size_t>(index) * 4u;
        if (palettePos + 4u > kPalette.size() || outPos + runBytes > out.size()) {
            return {};
        }

        for (std::size_t i = 0; i < count; ++i) {
            out[outPos++] = kPalette[palettePos + 0];
            out[outPos++] = kPalette[palettePos + 1];
            out[outPos++] = kPalette[palettePos + 2];
            out[outPos++] = kPalette[palettePos + 3];
        }
    }

    if (outPos != out.size()) {
        return {};
    }
    return out;
}

